INSERT INTO pokemons (nome, tipo, categoria, numero, descricao, imagem_url) VALUES
    ('Bulbasaur', 'Planta/Venenoso', 'iniciais', 1, 'Um Pokémon do tipo Planta/Venenoso. Ele tem uma semente nas costas desde o nascimento.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/001.png'),
    ('Charmander', 'Fogo', 'iniciais', 4, 'Um Pokémon do tipo Fogo. A chama em sua cauda indica sua força vital.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/004.png'),
    ('Squirtle', 'Água', 'iniciais', 7, 'Um Pokémon do tipo Água. Sua concha não é apenas para proteção, mas para nadar rapidamente.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/007.png'),
    ('Chikorita', 'Planta', 'iniciais', 152, 'Um Pokémon do tipo Planta. Usa a folha em sua cabeça para medir a temperatura e a umidade do ar.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/152.png'),
    ('Cyndaquil', 'Fogo', 'iniciais', 155, 'Um Pokémon do tipo Fogo. Solta chamas pelas costas quando está bravo ou assustado.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/155.png'),
    ('Totodile', 'Água', 'iniciais', 158, 'Um Pokémon do tipo Água. Tem mandíbulas fortes e o hábito de morder tudo o que vê pela frente.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/158.png'),
    ('Rattata', 'Normal', 'roedores', 19, 'Um Pokémon do tipo Normal. É muito comum e tem dentes fortes para roer qualquer coisa.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/019.png'),
    ('Bidoof', 'Normal', 'roedores', 399, 'Um Pokémon do tipo Normal. Conhecido por seus grandes dentes frontais e natureza calma.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/399.png'),
    ('Sentret', 'Normal', 'roedores', 161, 'Um Pokémon do tipo Normal. Ele se apoia em sua cauda para vigiar os arredores.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/161.png'),
    ('Zigzagoon', 'Normal', 'roedores', 263, 'Um Pokémon do tipo Normal. Anda sempre em zigue-zague e tem muita curiosidade por objetos perdidos.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/263.png'),
    ('Patrat', 'Normal', 'roedores', 504, 'Um Pokémon do tipo Normal. Mantém alimentos nas bochechas e vigia o território por dias sem dormir.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/504.png'),
    ('Bunnelby', 'Normal', 'roedores', 659, 'Um Pokémon do tipo Normal. Usa suas orelhas largas como pás para cavar buracos na terra rapidamente.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/659.png'),
    ('Pichu', 'Elétrico', 'pikaclones', 172, 'Um Pokémon do tipo Elétrico. A pré-evolução do Pikachu, ainda não controla bem sua eletricidade.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/172.png'),
    ('Plusle', 'Elétrico', 'pikaclones', 311, 'Um Pokémon do tipo Elétrico. Ele torce por seus parceiros criando faíscas positivas.', 'https://www.pokemon.com/static-assets/content-assets/cms2/img/pokedex/detail/311.png'),
