-- Catálogo inicial (os 50 Pokémon do Trabalho 1)
-- Pode ser executado mais de uma vez: atualiza quem já existe.
USE pokedex;

ON DUPLICATE KEY UPDATE
    tipo = VALUES(tipo),
    categoria = VALUES(categoria),
    numero = VALUES(numero),
    descricao = VALUES(descricao),
    imagem_url = VALUES(imagem_url);